/** Stored ZIP (no extra dependency). All entry names are generated by the server. */
export function zipFiles(files:{name:string;bytes:Buffer}[]){
 const table=Array.from({length:256},(_,n)=>{for(let k=0;k<8;k++)n=n&1?0xedb88320^(n>>>1):n>>>1;return n>>>0;});
 const crc=(b:Buffer)=>{let n=0xffffffff;for(const value of b)n=table[(n^value)&255]^(n>>>8);return(n^0xffffffff)>>>0;};
 const chunks:Buffer[]=[],central:Buffer[]=[];let offset=0,size=0;
 for(const file of files){if(!/^[a-zA-Z0-9_./-]+$/.test(file.name)||file.name.includes('..')||file.name.startsWith('/'))throw Error('Invalid archive entry');const name=Buffer.from(file.name),checksum=crc(file.bytes),local=Buffer.alloc(30);local.writeUInt32LE(0x04034b50);local.writeUInt16LE(20,4);local.writeUInt16LE(0x800,6);local.writeUInt16LE(0x21,12);local.writeUInt32LE(checksum,14);local.writeUInt32LE(file.bytes.length,18);local.writeUInt32LE(file.bytes.length,22);local.writeUInt16LE(name.length,26);chunks.push(local,name,file.bytes);const header=Buffer.alloc(46);header.writeUInt32LE(0x02014b50);header.writeUInt16LE(20,4);header.writeUInt16LE(20,6);header.writeUInt16LE(0x800,8);header.writeUInt16LE(0x21,14);header.writeUInt32LE(checksum,16);header.writeUInt32LE(file.bytes.length,20);header.writeUInt32LE(file.bytes.length,24);header.writeUInt16LE(name.length,28);header.writeUInt32LE(offset,42);central.push(header,name);offset+=local.length+name.length+file.bytes.length;size+=header.length+name.length;}
 const end=Buffer.alloc(22);end.writeUInt32LE(0x06054b50);end.writeUInt16LE(files.length,8);end.writeUInt16LE(files.length,10);end.writeUInt32LE(size,12);end.writeUInt32LE(offset,16);return Buffer.concat([...chunks,...central,end]);
}
